#!/usr/bin/env node
/**
 * scripts/fix-corrupted-speaker-labels.mjs — one-time repair pass (T-003 phase 4 follow-up,
 * real bug found by the checker 2026-09-04): applies `parseDiarizedTranscript`'s new
 * implausible-speaker-label guard to ALREADY-WRITTEN `turns.json` files, since those were
 * generated by the old, unguarded parser and never re-transcribed. Scans all 23 real sessions
 * (not just the ones the checker happened to sample) for turns whose `speakerRef` exceeds the
 * same plausibility threshold, merges the swallowed text back into the turn's own content, and
 * reassigns the speaker from the nearest preceding plausible turn — mirrors the parser's fix
 * exactly, applied to already-parsed JSON instead of raw model text, so no re-transcription (and
 * no non-deterministic re-roll of otherwise-correct content) is needed.
 *
 * Usage: node scripts/fix-corrupted-speaker-labels.mjs [--dry-run]
 */
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const MAX_PLAUSIBLE_SPEAKER_LABEL_LENGTH = 60;
const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const DATA_DIR = join(ROOT, "data", "toc-migrated");
const dryRun = process.argv.includes("--dry-run");

let totalFixed = 0;
for (const sessionId of readdirSync(DATA_DIR)) {
  const turnsPath = join(DATA_DIR, sessionId, "turns.json");
  let turns;
  try {
    turns = JSON.parse(readFileSync(turnsPath, "utf8"));
  } catch {
    continue; // no turns.json for this dir
  }
  if (!Array.isArray(turns) || turns.length === 0) continue;

  let lastPlausibleSpeaker = "spk:0";
  let fixedInThisSession = 0;
  const repaired = turns.map((t) => {
    if (typeof t.speakerRef === "string" && t.speakerRef.length > MAX_PLAUSIBLE_SPEAKER_LABEL_LENGTH) {
      fixedInThisSession++;
      return { ...t, speakerRef: lastPlausibleSpeaker, text: `${t.speakerRef}: ${t.text}`.trim() };
    }
    if (typeof t.speakerRef === "string" && t.speakerRef !== "unknown") lastPlausibleSpeaker = t.speakerRef;
    return t;
  });

  if (fixedInThisSession > 0) {
    console.log(`${sessionId}: ${fixedInThisSession} corrupted speakerRef turn(s) repaired`);
    totalFixed += fixedInThisSession;
    if (!dryRun) writeFileSync(turnsPath, JSON.stringify(repaired, null, 2) + "\n", "utf8");
  }
}

console.log(`\n${totalFixed} total corrupted turn(s) ${dryRun ? "found (dry run, not written)" : "repaired"} across all sessions.`);
